    'Deɛ ɔgye no die no, wɔmmu no fɔ; na deɛ ɔnnye nnie no deɛ, wɔabu no fɔ dada, ɛfiri sɛ wannye Onyankopɔn Ba a ɔwoo no korɔ no din annie.',
    'Na afobuo no nie, sɛ hann no aba wiase, na nnipa dɔɔ esum sene hann no, ɛfiri sɛ wɔn nnwuma yɛ bɔne.',
